'use client';

import { FC, useState, useRef, useEffect } from 'react';
import { Send, Upload, FileText, X, Bot, User, Brain, Search } from 'lucide-react';

interface Message {
  id: string;
  content: string;
  role: 'user' | 'assistant';
  timestamp: Date;
  type: 'text' | 'thinking';
  thoughtProcess?: {
    steps: string[];
    conclusion: string;
  };
}

const styles = `
  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(10px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  .animate-fade-in {
    animation: fadeIn 0.3s ease-out forwards;
  }
`;

const ChatPage: FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [isUploading, setIsUploading] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState<File[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  useEffect(() => {
    const styleSheet = document.createElement("style");
    styleSheet.textContent = styles;
    document.head.appendChild(styleSheet);
    return () => {
      document.head.removeChild(styleSheet);
    };
  }, []);

  const handleSend = async () => {
    if (!input.trim()) return;

    // Add user message
    const userMessage: Message = {
      id: Date.now().toString(),
      content: input,
      role: 'user',
      timestamp: new Date(),
      type: 'text',
    };
    setMessages((prev) => [...prev, userMessage]);
    setInput('');

    // Add thinking message
    const thinkingMessage: Message = {
      id: (Date.now() + 1).toString(),
      content: "Analyzing your request...",
      role: 'assistant',
      timestamp: new Date(),
      type: 'thinking',
      thoughtProcess: {
        steps: [
          "Analyzing the request type and context",
          "Determining the appropriate agent to handle the query",
          "Processing the request",
          "Generating a response"
        ],
        conclusion: "Processing your request..."
      }
    };
    setMessages((prev) => [...prev, thinkingMessage]);

    try {
      // Call the orchestrator API
      const response = await fetch('/api/chat', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ message: input }),
      });

      if (!response.ok) {
        throw new Error('Failed to get response');
      }

      const result = await response.json();

      // Remove thinking message
      setMessages((prev) => prev.filter(msg => msg.id !== thinkingMessage.id));

      // Add AI response
      const aiMessage: Message = {
        id: (Date.now() + 2).toString(),
        content: result.response,
        role: 'assistant',
        timestamp: new Date(),
        type: 'text',
        thoughtProcess: {
          steps: [
            `Query classified as: ${result.agent_type}`,
            `Processed by: ${result.agent_used}`,
            `Response generated successfully`
          ],
          conclusion: `Successfully processed your request using ${result.agent_used}`
        }
      };
      setMessages((prev) => [...prev, aiMessage]);

    } catch (error) {
      console.error('Error:', error);
      // Remove thinking message
      setMessages((prev) => prev.filter(msg => msg.id !== thinkingMessage.id));
      
      // Add error message
      const errorMessage: Message = {
        id: (Date.now() + 2).toString(),
        content: "I apologize, but I encountered an error while processing your request. Please try again.",
        role: 'assistant',
        timestamp: new Date(),
        type: 'text',
      };
      setMessages((prev) => [...prev, errorMessage]);
    }
  };

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files || []);
    setUploadedFiles((prev) => [...prev, ...files]);
  };

  const handleRemoveFile = (index: number) => {
    setUploadedFiles((prev) => prev.filter((_, i) => i !== index));
  };

  return (
    <div className="flex h-screen bg-gray-100">
      {/* Main Chat Area */}
      <div className="flex-1 flex flex-col">
        {/* Chat Header */}
        <div className="bg-white border-b p-4 flex items-center justify-between">
          <h1 className="text-xl font-semibold">Chat</h1>
          <div className="flex items-center space-x-4">
            <button
              onClick={() => document.getElementById('file-upload')?.click()}
              className="p-2 hover:bg-gray-100 rounded-full"
              title="Upload Files"
            >
              <Upload className="w-5 h-5" />
            </button>
            <input
              id="file-upload"
              type="file"
              multiple
              className="hidden"
              onChange={handleFileUpload}
            />
          </div>
        </div>

        {/* Messages Area */}
        <div className="flex-1 overflow-y-auto p-4 space-y-4">
          {messages.map((message) => (
            <div
              key={message.id}
              className={`flex ${message.role === 'user' ? 'justify-end' : 'justify-start'}`}
            >
              <div
                className={`max-w-[70%] rounded-lg p-4 ${
                  message.role === 'user'
                    ? 'bg-blue-500 text-white'
                    : 'bg-white border'
                }`}
              >
                {message.type === 'thinking' ? (
                  <div className="space-y-2">
                    <p>{message.content}</p>
                    {message.thoughtProcess && (
                      <div className="mt-2 text-sm">
                        <div className="space-y-1">
                          {message.thoughtProcess.steps.map((step, index) => (
                            <div key={index} className="flex items-center space-x-2">
                              <div className="w-2 h-2 bg-gray-400 rounded-full animate-pulse" />
                              <span>{step}</span>
                            </div>
                          ))}
                        </div>
                        <p className="mt-2 font-medium">{message.thoughtProcess.conclusion}</p>
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="prose">
                    <p className="whitespace-pre-wrap">{message.content}</p>
                    {message.thoughtProcess && (
                      <div className="mt-2 text-sm text-gray-500">
                        <div className="space-y-1">
                          {message.thoughtProcess.steps.map((step, index) => (
                            <div key={index} className="flex items-center space-x-2">
                              <div className="w-2 h-2 bg-gray-400 rounded-full" />
                              <span>{step}</span>
                            </div>
                          ))}
                        </div>
                        <p className="mt-2 font-medium">{message.thoughtProcess.conclusion}</p>
                      </div>
                    )}
                  </div>
                )}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>

        {/* Uploaded Files */}
        {uploadedFiles.length > 0 && (
          <div className="border-t p-4 bg-white">
            <div className="flex flex-wrap gap-2">
              {uploadedFiles.map((file, index) => (
                <div
                  key={index}
                  className="flex items-center space-x-2 bg-gray-100 rounded-lg px-3 py-2"
                >
                  <FileText className="w-4 h-4" />
                  <span className="text-sm">{file.name}</span>
                  <button
                    onClick={() => handleRemoveFile(index)}
                    className="text-gray-500 hover:text-gray-700"
                  >
                    <X className="w-4 h-4" />
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Input Area */}
        <div className="border-t p-4 bg-white">
          <div className="flex space-x-4">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyPress={(e) => e.key === 'Enter' && handleSend()}
              placeholder="Type your message..."
              className="flex-1 border rounded-lg px-4 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
            <button
              onClick={handleSend}
              disabled={!input.trim()}
              className="bg-blue-500 text-white px-6 py-2 rounded-lg hover:bg-blue-600 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Send className="w-5 h-5" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ChatPage; 